import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
export const DOCS_DIR = path.join(here, 'docs');

// Read every .md file in server/rag/docs. Returns [{ source, title, text }].
export function loadDocs() {
  return fs.readdirSync(DOCS_DIR)
    .filter((f) => f.endsWith('.md'))
    .sort()
    .map((file) => {
      const raw = fs.readFileSync(path.join(DOCS_DIR, file), 'utf8').trim();
      const title = (raw.match(/^#\s+(.+)$/m) || [])[1] || file;
      return { source: file, title, text: raw.replace(/^#\s+.+\n+/, '') };
    });
}

// Naive chunking for lesson 13: one paragraph = one chunk.
// Lesson 14 replaces this with better chunking.
export function paragraphChunks() {
  const chunks = [];
  for (const doc of loadDocs()) {
    doc.text.split(/\n{2,}/).map((p) => p.trim()).filter(Boolean).forEach((text, i) => {
      chunks.push({ id: `${doc.source}#${i + 1}`, source: doc.source, title: doc.title, text });
    });
  }
  return chunks;
}

// Keyword retrieval: the simplest useful search.
// Score = how many rare words the question and the chunk share.

const STOP = new Set('a an the and or of to in on at for with from by is are was were be been it this that these those i you we they my your our their me do does did how what when where why which can should would will not no yes as if but so than then there here about into over'.split(' '));

// A very light "stemmer": pages -> page, formatting -> formatt, skills -> skill.
// It is crude on purpose. It only needs to make the same word look the same.
const stem = (w) => (w.length > 4 ? w.replace(/(ing|ed|es|s)$/, '') : w);

export const tokenize = (text) =>
  (String(text).toLowerCase().match(/[a-z0-9][a-z0-9+#.-]*/g) || [])
    .map((w) => w.replace(/[.-]+$/, ''))
    .filter((w) => w.length > 1 && !STOP.has(w))
    .map(stem);

export function keywordSearch(question, chunks, k = 3) {
  const q = [...new Set(tokenize(question))];
  const docFreq = new Map();
  const tokenized = chunks.map((c) => new Set(tokenize(c.text + ' ' + c.title)));
  for (const set of tokenized) for (const t of set) docFreq.set(t, (docFreq.get(t) || 0) + 1);

  return chunks
    .map((chunk, i) => {
      let score = 0;
      for (const t of q) {
        if (tokenized[i].has(t)) score += Math.log(1 + chunks.length / (docFreq.get(t) || 1));
      }
      return { ...chunk, score: Number(score.toFixed(3)) };
    })
    .filter((c) => c.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, k);
}

import { Router } from 'express';
import { client, MODEL, textOf } from '../claude.js';
import { paragraphChunks } from '../rag/load.js';
import { keywordSearch } from '../rag/keyword.js';

const router = Router();
const chunks = paragraphChunks(); // read once when the server starts

const SYSTEM = `You answer questions for a resume website using ONLY the context the user provides.
If the context does not contain the answer, say exactly: "I don't have that in my notes."
Keep answers short and in plain English. Do not use outside knowledge.`;

// POST /api/rag  { question }  ->  { answer, sources, usedModel }
router.post('/rag', async (req, res) => {
  const question = String(req.body?.question || '').trim().slice(0, 500);
  if (!question) return res.status(400).json({ error: { message: 'Please type a question.' } });

  // 1. Retrieve: find the 3 best chunks.
  const sources = keywordSearch(question, chunks, 3);

  // No match at all: do not even call the model, it would only guess.
  if (!sources.length) {
    return res.json({ answer: "I don't have that in my notes.", sources: [], usedModel: false });
  }

  // 2. Augment: put the chunks into the prompt, inside tags so the model can tell data from instructions.
  const context = sources.map((s, i) => `<chunk id="${i + 1}" source="${s.source}">\n${s.text}\n</chunk>`).join('\n');

  // 3. Generate: ask the model to answer from that context only.
  const reply = await client.messages.create({
    model: MODEL,
    max_tokens: 400,
    system: SYSTEM,
    messages: [{ role: 'user', content: `<context>\n${context}\n</context>\n\nQuestion: ${question}` }],
  });

  res.json({ answer: textOf(reply), sources, usedModel: true });
});

export default router;

import { Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { errorText } from '../util';

type Source = { id: string; source: string; text: string; score: number };

@Component({
  selector: 'app-rag',
  imports: [FormsModule],
  template: `
    <h1>Ask the help center (RAG)</h1>
    <p class="hint">The server finds the best paragraphs in our own documents, then asks Claude to answer from them only.</p>

    <div class="card">
      <label for="q">Your question</label>
      <input id="q" [(ngModel)]="question" (keyup.enter)="ask()" />
      <button (click)="ask()" [disabled]="busy() || !question.trim()">{{ busy() ? 'Searching...' : 'Ask' }}</button>
      @if (error()) { <div class="err">{{ error() }}</div> }
    </div>

    @if (answer()) {
      <div class="card">
        <h2>Answer</h2>
        <div class="answer">{{ answer() }}</div>
        <h2>Sources used ({{ sources().length }})</h2>
        @for (s of sources(); track s.id) {
          <p><strong>{{ s.source }}</strong> <span class="muted">score {{ s.score }}</span></p>
          <pre class="out">{{ s.text }}</pre>
        } @empty {
          <p class="muted">Nothing matched, so the model was not called.</p>
        }
      </div>
    }
  `,
})
export class RagPage {
  private http = inject(HttpClient);

  question = 'How many pages should my resume be?';
  busy = signal(false);
  error = signal('');
  answer = signal('');
  sources = signal<Source[]>([]);

  async ask() {
    this.busy.set(true);
    this.error.set('');
    this.answer.set('');
    try {
      const r = await firstValueFrom(this.http.post<{ answer: string; sources: Source[] }>('/api/rag', { question: this.question }));
      this.answer.set(r.answer);
      this.sources.set(r.sources);
    } catch (e) {
      this.error.set(errorText(e));
    } finally {
      this.busy.set(false);
    }
  }
}

// Split text into overlapping chunks of about `size` words.
// Overlap repeats the last few words of one chunk at the start of the next,
// so a sentence cut at the border still appears whole in one of them.
export function chunkWords(text, { size = 80, overlap = 20 } = {}) {
  size = Math.max(10, Math.floor(size));
  overlap = Math.min(Math.max(0, Math.floor(overlap)), size - 1);
  const words = String(text).split(/\s+/).filter(Boolean);
  const out = [];
  for (let start = 0; start < words.length; start += size - overlap) {
    out.push(words.slice(start, start + size).join(' '));
    if (start + size >= words.length) break; // the last chunk reached the end
  }
  return out;
}

// A tiny LOCAL embedding so the lab works without any key.
// It turns text into a vector of 512 numbers by hashing words and word pairs.
// Texts that share words get similar vectors. It does NOT understand synonyms:
// "car" and "automobile" look unrelated to it. A real embedding model does.
// In a real product, replace embed() with a call to an embedding model.
import { tokenize } from './keyword.js';

export const DIMS = 1024;

function hash(str) {
  let h = 2166136261; // FNV-1a
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}


export function embed(text) {
  const vec = new Float64Array(DIMS);
  const w = tokenize(text); // content words only: no "the" or "of"
  const features = [...w, ...w.slice(1).map((x, i) => `${w[i]}_${x}`)]; // words and word pairs
  for (const f of features) {
    const h = hash(f);
    vec[h % DIMS] += h & 0x100 ? 1 : -1; // a second bit of the hash picks the sign
  }
  for (let i = 0; i < DIMS; i++) vec[i] = Math.sign(vec[i]) * Math.log1p(Math.abs(vec[i]));
  const norm = Math.sqrt(vec.reduce((s, x) => s + x * x, 0)) || 1;
  return Array.from(vec, (x) => Math.round((x / norm) * 1e4) / 1e4); // length ~1, so cosine = dot product; 4 decimals keep files small
}

export const cosine = (a, b) => a.reduce((s, x, i) => s + x * b[i], 0);

import { loadDocs } from './load.js';
import { chunkWords } from './chunk.js';
import { embed, cosine } from './embed.js';

const cache = new Map(); // "size:overlap" -> chunks with vectors

// Chunk every document and embed every chunk. Cached per setting.
export function buildIndex({ size = 80, overlap = 20 } = {}) {
  const key = `${size}:${overlap}`;
  if (cache.has(key)) return cache.get(key);
  const chunks = [];
  for (const doc of loadDocs()) {
    chunkWords(doc.text, { size, overlap }).forEach((text, i) => {
      chunks.push({ id: `${doc.source}#${i + 1}`, source: doc.source, title: doc.title, text, vector: embed(`${doc.title}. ${text}`) });
    });
  }
  cache.set(key, chunks);
  return chunks;
}

// Vector search: embed the question, rank chunks by cosine similarity.
export function vectorSearch(query, { size = 80, overlap = 20, k = 4 } = {}) {
  const q = embed(query);
  return buildIndex({ size, overlap })
    .map(({ vector, ...c }) => ({ ...c, score: Number(cosine(q, vector).toFixed(4)) }))
    .sort((a, b) => b.score - a.score)
    .slice(0, k);
}

import { Router } from 'express';
import { buildIndex, vectorSearch } from '../rag/index.js';

const router = Router();
const num = (v, d, min, max) => Math.min(max, Math.max(min, Number.isFinite(Number(v)) ? Number(v) : d));

// POST /api/search  { query, size, overlap, k }  ->  { chunkCount, hits }
// No Claude call here: this lesson is about retrieval only, so it is free and fast.
router.post('/search', (req, res) => {
  const query = String(req.body?.query || '').trim().slice(0, 300);
  if (!query) return res.status(400).json({ error: { message: 'Please type something to search for.' } });
  const size = num(req.body?.size, 80, 20, 300);
  const overlap = num(req.body?.overlap, 20, 0, size - 1);
  const k = num(req.body?.k, 4, 1, 10);

  res.json({
    chunkCount: buildIndex({ size, overlap }).length,
    hits: vectorSearch(query, { size, overlap, k }),
  });
});

export default router;

import { Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { errorText } from '../util';

type Hit = { id: string; source: string; text: string; score: number };

@Component({
  selector: 'app-search',
  imports: [FormsModule],
  template: `
    <h1>Chunks and vector search</h1>
    <p class="hint">Change the chunk size and overlap and watch which chunks come back. No Claude call, no cost.</p>

    <div class="card">
      <label for="q">Search for</label>
      <input id="q" [(ngModel)]="query" (keyup.enter)="run()" />
      <div class="grid2">
        <div><label for="s">Chunk size (words): {{ size }}</label><input id="s" type="range" min="20" max="200" step="10" [(ngModel)]="size" /></div>
        <div><label for="o">Overlap (words): {{ overlap }}</label><input id="o" type="range" min="0" max="60" step="5" [(ngModel)]="overlap" /></div>
      </div>
      <button (click)="run()" [disabled]="busy() || !query.trim()">{{ busy() ? 'Searching...' : 'Search' }}</button>
      @if (error()) { <div class="err">{{ error() }}</div> }
    </div>

    @if (hits().length) {
      <div class="card">
        <h2>Top {{ hits().length }} of {{ chunkCount() }} chunks</h2>
        @for (h of hits(); track h.id) {
          <p><strong>{{ h.id }}</strong> <span class="muted">similarity {{ h.score }}</span></p>
          <div class="bar"><span [style.width.%]="percent(h.score)"></span></div>
          <pre class="out">{{ h.text }}</pre>
        }
      </div>
    }
  `,
  styles: [`.bar { height:8px; background:#e2e8f0; border-radius:99px; margin:4px 0 6px; } .bar span { display:block; height:100%; background:#4f46e5; border-radius:99px; }`],
})
export class SearchPage {
  private http = inject(HttpClient);

  query = 'what should go in the skills section for the ATS';
  size = 80;
  overlap = 20;
  busy = signal(false);
  error = signal('');
  hits = signal<Hit[]>([]);
  chunkCount = signal(0);

  percent(score: number) {
    return Math.max(2, Math.min(100, Math.round(score * 100)));
  }

  async run() {
    this.busy.set(true);
    this.error.set('');
    try {
      const r = await firstValueFrom(
        this.http.post<{ chunkCount: number; hits: Hit[] }>('/api/search', { query: this.query, size: Number(this.size), overlap: Number(this.overlap), k: 4 }),
      );
      this.hits.set(r.hits);
      this.chunkCount.set(r.chunkCount);
    } catch (e) {
      this.error.set(errorText(e));
    } finally {
      this.busy.set(false);
    }
  }
}

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { loadDocs } from './load.js';
import { chunkWords } from './chunk.js';
import { embed, cosine } from './embed.js';

// A vector store has four jobs: upsert, remove, query and count.
// Keep them behind one small interface and you can swap the engine later
// (pgvector, Qdrant, Pinecone, Chroma) without touching the routes.

export class MemoryStore {
  constructor() {
    this.items = new Map(); // id -> { id, source, title, text, vector }
  }

  upsert(item) {
    this.items.set(item.id, { ...item, vector: item.vector || embed(`${item.title || ''}. ${item.text}`) });
    return item.id;
  }

  remove(id) {
    return this.items.delete(id);
  }

  count() {
    return this.items.size;
  }

  list() {
    return [...this.items.values()].map(({ vector, ...rest }) => rest);
  }

  // Nearest neighbours by cosine similarity. `source` is a metadata filter.
  query(text, { k = 4, source } = {}) {
    const q = embed(text);
    return [...this.items.values()]
      .filter((it) => !source || it.source === source)
      .map(({ vector, ...rest }) => ({ ...rest, score: Number(cosine(q, vector).toFixed(4)) }))
      .sort((a, b) => b.score - a.score)
      .slice(0, k);
  }
}

// Same store, but saved to a JSON file so data survives a restart.
export class FileStore extends MemoryStore {
  constructor(file) {
    super();
    this.file = file;
    if (fs.existsSync(file)) {
      for (const it of JSON.parse(fs.readFileSync(file, 'utf8'))) this.items.set(it.id, it);
    }
  }

  save() {
    fs.mkdirSync(path.dirname(this.file), { recursive: true });
    fs.writeFileSync(this.file, JSON.stringify([...this.items.values()]));
  }

  upsert(item) {
    const id = super.upsert(item);
    this.save();
    return id;
  }

  remove(id) {
    const done = super.remove(id);
    if (done) this.save();
    return done;
  }
}

const here = path.dirname(fileURLToPath(import.meta.url));
let store;

// One shared store for the whole server.
// On every start the documents in server/rag/docs are re-chunked and re-embedded, so editing a
// document and restarting always works. Notes you added yourself (other sources) are kept.
export function getStore() {
  if (store) return store;
  store = new FileStore(process.env.VECTOR_FILE || path.join(here, '..', 'runtime', 'vectors.json'));
  const docs = loadDocs();
  const docSources = new Set(docs.map((d) => d.source));
  for (const [id, item] of [...store.items]) if (docSources.has(item.source)) store.items.delete(id);
  for (const doc of docs) {
    chunkWords(doc.text, { size: 80, overlap: 20 }).forEach((text, i) => {
      const id = `${doc.source}#${i + 1}`;
      store.items.set(id, { id, source: doc.source, title: doc.title, text, vector: embed(`${doc.title}. ${text}`) });
    });
  }
  store.save();
  return store;
}

import { Router } from 'express';
import { getStore } from '../rag/store.js';

const router = Router();

// GET /api/store  ->  { count, sources, items }
router.get('/store', (req, res) => {
  const items = getStore().list();
  res.json({ count: items.length, sources: [...new Set(items.map((i) => i.source))], items });
});

// POST /api/store/query  { query, source?, k? }  ->  { hits }
router.post('/store/query', (req, res) => {
  const query = String(req.body?.query || '').trim().slice(0, 300);
  if (!query) return res.status(400).json({ error: { message: 'Please type a query.' } });
  const source = req.body?.source ? String(req.body.source).slice(0, 100) : undefined;
  const k = Math.min(10, Math.max(1, Number(req.body?.k) || 4));
  res.json({ hits: getStore().query(query, { k, source }) });
});

// POST /api/store/upsert  { text, source?, id? }  ->  { id, count }
router.post('/store/upsert', (req, res) => {
  const text = String(req.body?.text || '').trim().slice(0, 4000);
  if (text.length < 10) return res.status(400).json({ error: { message: 'Write at least 10 characters.' } });
  const source = String(req.body?.source || 'my-notes.md').slice(0, 100);
  const store = getStore();
  const id = String(req.body?.id || `${source}#${Date.now().toString(36)}`).slice(0, 120);
  store.upsert({ id, source, title: source, text });
  res.json({ id, count: store.count() });
});

// DELETE /api/store/:id  ->  { removed, count }
router.delete('/store/:id', (req, res) => {
  const store = getStore();
  const removed = store.remove(req.params.id);
  if (!removed) return res.status(404).json({ error: { message: 'No such item.' } });
  res.json({ removed: true, count: store.count() });
});

export default router;

import { Component, inject, signal, OnInit } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { errorText } from '../util';

type Item = { id: string; source: string; text: string; score?: number };

@Component({
  selector: 'app-store',
  imports: [FormsModule],
  template: `
    <h1>Vector store</h1>
    <p class="hint">Add your own notes, search them by meaning, filter by source and delete them. Data is saved in server/runtime/vectors.json.</p>

    <div class="card">
      <h2>Add a note</h2>
      <textarea [(ngModel)]="newText" placeholder="Write something to remember..." style="min-height:90px"></textarea>
      <button (click)="add()" [disabled]="busy() || newText.trim().length < 10">Add to store</button>
    </div>

    <div class="card">
      <h2>Search ({{ count() }} items)</h2>
      <input [(ngModel)]="query" (keyup.enter)="search()" placeholder="Search by meaning..." />
      <label for="src">Only this source (optional)</label>
      <select id="src" [(ngModel)]="source">
        <option value="">All sources</option>
        @for (s of sources(); track s) { <option [value]="s">{{ s }}</option> }
      </select>
      <button (click)="search()" [disabled]="busy() || !query.trim()">Search</button>
      @if (error()) { <div class="err">{{ error() }}</div> }
      @for (h of hits(); track h.id) {
        <p><strong>{{ h.id }}</strong> <span class="muted">similarity {{ h.score }}</span>
          <button class="danger" style="margin-left:8px" (click)="remove(h.id)">Delete</button></p>
        <pre class="out">{{ h.text }}</pre>
      }
    </div>
  `,
})
export class StorePage implements OnInit {
  private http = inject(HttpClient);

  newText = '';
  query = 'how do I protect my personal details';
  source = '';
  busy = signal(false);
  error = signal('');
  count = signal(0);
  sources = signal<string[]>([]);
  hits = signal<Item[]>([]);

  ngOnInit() {
    this.refresh();
  }

  private async guard(fn: () => Promise<void>) {
    this.busy.set(true);
    this.error.set('');
    try {
      await fn();
    } catch (e) {
      this.error.set(errorText(e));
    } finally {
      this.busy.set(false);
    }
  }

  refresh() {
    return this.guard(async () => {
      const r = await firstValueFrom(this.http.get<{ count: number; sources: string[] }>('/api/store'));
      this.count.set(r.count);
      this.sources.set(r.sources);
    });
  }

  add() {
    return this.guard(async () => {
      await firstValueFrom(this.http.post('/api/store/upsert', { text: this.newText, source: 'my-notes.md' }));
      this.newText = '';
      const r = await firstValueFrom(this.http.get<{ count: number; sources: string[] }>('/api/store'));
      this.count.set(r.count);
      this.sources.set(r.sources);
    });
  }

  search() {
    return this.guard(async () => {
      const r = await firstValueFrom(this.http.post<{ hits: Item[] }>('/api/store/query', { query: this.query, source: this.source || undefined }));
      this.hits.set(r.hits);
    });
  }

  remove(id: string) {
    return this.guard(async () => {
      await firstValueFrom(this.http.delete(`/api/store/${encodeURIComponent(id)}`));
      this.hits.update((h) => h.filter((x) => x.id !== id));
      const r = await firstValueFrom(this.http.get<{ count: number; sources: string[] }>('/api/store'));
      this.count.set(r.count);
      this.sources.set(r.sources);
    });
  }
}

import { tokenize } from './keyword.js';

// BM25: the standard keyword ranking used by search engines.
// It improves plain keyword matching in two ways:
//  - a word repeated many times helps less and less (saturation, k1)
//  - long chunks are not unfairly favoured (length normalisation, b)
export function bm25Search(query, chunks, k = 8, { k1 = 1.5, b = 0.75 } = {}) {
  const docs = chunks.map((c) => tokenize(`${c.title || ''} ${c.text}`));
  const avgLen = docs.reduce((s, d) => s + d.length, 0) / (docs.length || 1);
  const df = new Map();
  for (const d of docs) for (const t of new Set(d)) df.set(t, (df.get(t) || 0) + 1);
  const q = [...new Set(tokenize(query))];

  return chunks
    .map((chunk, i) => {
      const tf = new Map();
      for (const t of docs[i]) tf.set(t, (tf.get(t) || 0) + 1);
      let score = 0;
      for (const t of q) {
        const f = tf.get(t) || 0;
        if (!f) continue;
        const idf = Math.log(1 + (docs.length - df.get(t) + 0.5) / (df.get(t) + 0.5));
        score += idf * ((f * (k1 + 1)) / (f + k1 * (1 - b + b * (docs[i].length / avgLen))));
      }
      return { ...chunk, score: Number(score.toFixed(4)) };
    })
    .filter((c) => c.score > 0)
    .sort((a, b2) => b2.score - a.score)
    .slice(0, k);
}

import { getStore } from './store.js';
import { bm25Search } from './bm25.js';
import { tokenize } from './keyword.js';

// Reciprocal Rank Fusion: combine several ranked lists using only the RANK of each item.
// Scores from different systems (BM25 and cosine) are not comparable, ranks are.
export function rrf(lists, { k = 60 } = {}) {
  const fused = new Map();
  for (const list of lists) {
    list.forEach((item, rank) => {
      const entry = fused.get(item.id) || { ...item, score: 0 };
      entry.score += 1 / (k + rank + 1);
      fused.set(item.id, entry);
    });
  }
  return [...fused.values()].map((x) => ({ ...x, score: Number(x.score.toFixed(5)) })).sort((a, b) => b.score - a.score);
}

// A very small "reranker": after the first search, look at the few best chunks again
// and favour the ones that contain MORE of the question's words in one place.
// Real systems use a cross-encoder model here; this shows where it fits.
export function rerank(query, items) {
  const q = [...new Set(tokenize(query))];
  return items
    .map((it) => {
      const words = new Set(tokenize(it.text));
      const covered = q.filter((t) => words.has(t)).length;
      return { ...it, coverage: q.length ? Number((covered / q.length).toFixed(2)) : 0 };
    })
    .sort((a, b) => b.coverage - a.coverage || b.score - a.score);
}

// Vector search ALWAYS returns the nearest chunks, even when nothing is near.
// Below this similarity a chunk is noise, so we drop it. Tune it on your own data.
export const MIN_SIMILARITY = 0.1;

// mode: 'keyword' | 'vector' | 'hybrid'
export function retrieve(query, { mode = 'hybrid', k = 4 } = {}) {
  const store = getStore();
  const all = [...store.items.values()];
  const keyword = bm25Search(query, all, 8);
  const vector = store.query(query, { k: 8 }).filter((h) => h.score >= MIN_SIMILARITY);
  if (mode === 'keyword') return keyword.slice(0, k);
  if (mode === 'vector') return vector.slice(0, k);
  return rerank(query, rrf([keyword, vector]).slice(0, 6)).slice(0, k);
}

import { Router } from 'express';
import { client, MODEL, textOf } from '../claude.js';
import { retrieve } from '../rag/hybrid.js';

const router = Router();

const SYSTEM = `You answer questions for a resume website using ONLY the numbered sources provided.
After every sentence that uses a source, add its number in square brackets, like [1] or [2][3].
If the sources do not contain the answer, reply exactly: "I don't have that in my notes."
Never invent a source number. Keep the answer short and in plain English.`;

// POST /api/rag-plus  { question, mode }  ->  { answer, citations, sources, mode }
router.post('/rag-plus', async (req, res) => {
  const question = String(req.body?.question || '').trim().slice(0, 500);
  if (!question) return res.status(400).json({ error: { message: 'Please type a question.' } });
  const mode = ['keyword', 'vector', 'hybrid'].includes(req.body?.mode) ? req.body.mode : 'hybrid';

  const sources = retrieve(question, { mode, k: 4 });
  if (!sources.length) return res.json({ answer: "I don't have that in my notes.", citations: [], sources: [], mode });

  const context = sources.map((s, i) => `<source n="${i + 1}" file="${s.source}">\n${s.text}\n</source>`).join('\n');
  const reply = await client.messages.create({
    model: MODEL,
    max_tokens: 500,
    system: SYSTEM,
    messages: [{ role: 'user', content: `<sources>\n${context}\n</sources>\n\nQuestion: ${question}` }],
  });
  const answer = textOf(reply);

  // Check the citations: keep only numbers that really exist. A made-up [9] is dropped and reported.
  const cited = [...new Set([...answer.matchAll(/\[(\d+)\]/g)].map((m) => Number(m[1])))];
  const citations = cited.filter((n) => n >= 1 && n <= sources.length);
  const invalid = cited.filter((n) => n < 1 || n > sources.length);

  res.json({ answer, citations, invalidCitations: invalid, sources, mode });
});

export default router;

