// Remove personal data from text BEFORE it leaves your server for an AI provider.
// This is a first line of defence. Patterns miss things, so also tell users not to paste secrets.

const luhn = (digits) => {
  let sum = 0;
  let alt = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let n = Number(digits[i]);
    if (alt) { n *= 2; if (n > 9) n -= 9; }
    sum += n;
    alt = !alt;
  }
  return sum % 10 === 0;
};

// Order matters: longer, more specific patterns run first.
// (?<!\d[ -]?) and (?![ -]?\d) mean "not part of a longer number", so we never cut a number in half.
const RULES = [
  { type: 'EMAIL', re: /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi },
  { type: 'PAN', re: /\b[A-Z]{5}[0-9]{4}[A-Z]\b/g },
  { type: 'CARD', re: /(?<!\d[ -]?)\d(?:[ -]?\d){12,18}(?![ -]?\d)/g, check: (m) => luhn(m.replace(/\D/g, '')) },
  { type: 'AADHAAR', re: /(?<!\d[ -]?)[2-9]\d{3}[ -]?\d{4}[ -]?\d{4}(?![ -]?\d)/g },
  { type: 'PHONE', re: /(?<!\d[ -]?)(?:\+\d{1,3}[ -]?)?(?:\(?\d{2,5}\)?[ -]?)?\d{3,5}[ -]?\d{4,5}(?![ -]?\d)/g, check: (m) => m.replace(/\D/g, '').length >= 10 },
];

// Returns { text, found, map }. map lets you put the real values back into the reply for the user.
export function redact(input) {
  let text = String(input);
  const map = {};
  const counts = {};
  for (const { type, re, check } of RULES) {
    text = text.replace(re, (m) => {
      if (check && !check(m)) return m;
      counts[type] = (counts[type] || 0) + 1;
      const token = `[${type}_${counts[type]}]`;
      map[token] = m;
      return token;
    });
  }
  return { text, found: Object.entries(counts).map(([type, count]) => ({ type, count })), map };
}

export const restore = (text, map) => Object.entries(map).reduce((t, [token, value]) => t.split(token).join(value), String(text));

import { Router } from 'express';
import { client, MODEL, textOf } from '../claude.js';
import { redact, restore } from '../privacy.js';

const router = Router();

const clean = (v) => String(v || '').trim().slice(0, 8000);

// POST /api/privacy/preview  { text }  ->  { redacted, found }   (no AI call, free)
router.post('/privacy/preview', (req, res) => {
  const text = clean(req.body?.text);
  if (!text) return res.status(400).json({ error: { message: 'Please paste some text.' } });
  const { text: redacted, found } = redact(text);
  res.json({ redacted, found });
});

// POST /api/privacy/summarise  { text }  ->  { summary, sentToModel, found }
router.post('/privacy/summarise', async (req, res) => {
  const text = clean(req.body?.text);
  if (!text) return res.status(400).json({ error: { message: 'Please paste some text.' } });

  const { text: safe, found, map } = redact(text);
  const reply = await client.messages.create({
    model: MODEL,
    max_tokens: 400,
    system: 'Summarise the resume text in 3 short bullet points. Keep placeholders like [EMAIL_1] exactly as written.',
    messages: [{ role: 'user', content: `<resume>\n${safe}\n</resume>` }],
  });

  // The model never saw the real values. We put them back for the user only.
  res.json({ summary: restore(textOf(reply), map), sentToModel: safe, found });
});

