import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const LOG = path.join(here, 'runtime', 'usage.jsonl');

// ---- 1. Response cache: the same question within 10 minutes costs nothing. ----
const cache = new Map();
const TTL = 10 * 60 * 1000;
const MAX_ENTRIES = 200;
export const cacheKey = (...parts) => parts.map((p) => String(p).toLowerCase().replace(/\s+/g, ' ').trim()).join('|');
export const cacheGet = (key) => {
  const hit = cache.get(key);
  if (!hit) return null;
  if (hit.expires < Date.now()) { cache.delete(key); return null; }
  return hit.value;
};
export const cacheSet = (key, value) => {
  cache.set(key, { value, expires: Date.now() + TTL });
  if (cache.size > MAX_ENTRIES) cache.delete(cache.keys().next().value); // drop the oldest
};

// ---- 2. Rate limit: at most `limit` calls per client per minute. ----
const windows = new Map();
export function rateLimit({ limit = 10, windowMs = 60_000 } = {}) {
  return (req, res, next) => {
    const now = Date.now();
    const ip = req.ip || 'unknown';
    const w = windows.get(ip);
    if (!w || w.reset < now) {
      windows.set(ip, { count: 1, reset: now + windowMs });
      return next();
    }
    if (++w.count > limit) {
      res.setHeader('Retry-After', Math.ceil((w.reset - now) / 1000));
      return res.status(429).json({ error: { message: 'Too many requests. Please wait a minute and try again.', status: 429 } });
    }
    next();
  };
}

// ---- 3. Metrics and a usage log. ----
const m = { requests: 0, cacheHits: 0, fallbacks: 0, errors: 0, inputTokens: 0, outputTokens: 0, totalMs: 0 };

const price = () => ({
  input: Number(process.env.PRICE_INPUT_PER_MTOK) || 0,
  output: Number(process.env.PRICE_OUTPUT_PER_MTOK) || 0,
  currency: process.env.PRICE_CURRENCY || 'USD',
});

export function record({ route, ms, usage = { input: 0, output: 0 }, cached = false, fallback = false, error = false }) {
  m.requests++;
  m.totalMs += ms;
  if (cached) m.cacheHits++;
  if (fallback) m.fallbacks++;
  if (error) m.errors++;
  m.inputTokens += usage.input;
  m.outputTokens += usage.output;
  try {
    fs.mkdirSync(path.dirname(LOG), { recursive: true });
    // Log numbers only. Never write the user's text to a log file.
    fs.appendFileSync(LOG, JSON.stringify({ at: new Date().toISOString(), route, ms, cached, fallback, error, ...usage }) + '\n');
  } catch { /* logging must never break a request */ }
}

export function metrics() {
  const p = price();
  const cost = (m.inputTokens * p.input + m.outputTokens * p.output) / 1_000_000;
  return {
    ...m,
    avgMs: m.requests ? Math.round(m.totalMs / m.requests) : 0,
    cacheHitRate: m.requests ? Number((m.cacheHits / m.requests).toFixed(2)) : 0,
    estimatedCost: p.input || p.output ? Number(cost.toFixed(4)) : null,
    currency: p.currency,
  };
}

import { client, MODEL, textOf } from '../claude.js';
import { retrieve } from './hybrid.js';

const SYSTEM = `You answer questions for a resume website using ONLY the numbered sources provided.
After every sentence that uses a source, add its number in square brackets, like [1] or [2][3].
If the sources do not contain the answer, reply exactly: "I don't have that in my notes."
Never invent a source number. Keep the answer short and in plain English.`;

// Lesson 24 changes: the call now has a timeout and the result reports token usage.
export async function answerQuestion(question, mode = 'hybrid', { timeoutMs = 20000 } = {}) {
  const sources = retrieve(question, { mode, k: 4 });
  const usage = { input: 0, output: 0 };
  if (!sources.length) return { answer: "I don't have that in my notes.", citations: [], invalidCitations: [], sources: [], mode, usage };

  const context = sources.map((s, i) => `<source n="${i + 1}" file="${s.source}">\n${s.text}\n</source>`).join('\n');
  const reply = await client.messages.create(
    {
      model: MODEL,
      max_tokens: 500,
      system: SYSTEM,
      messages: [{ role: 'user', content: `<sources>\n${context}\n</sources>\n\nQuestion: ${question}` }],
    },
    { timeout: timeoutMs, maxRetries: 1 }, // fail fast: a slow answer is worse than a fallback
  );
  usage.input = reply.usage?.input_tokens || 0;
  usage.output = reply.usage?.output_tokens || 0;
  const answer = textOf(reply);
  const cited = [...new Set([...answer.matchAll(/\[(\d+)\]/g)].map((m) => Number(m[1])))];
  return {
    answer,
    citations: cited.filter((n) => n >= 1 && n <= sources.length),
    invalidCitations: cited.filter((n) => n < 1 || n > sources.length),
    sources,
    mode,
    usage,
  };
}

import { Router } from 'express';
import { answerQuestion } from '../rag/answer.js';
import { retrieve } from '../rag/hybrid.js';
import { cacheGet, cacheSet, cacheKey, rateLimit, record, metrics } from '../ops.js';

const router = Router();

// POST /api/ops/ask  { question }
// Cached, rate limited, timed, measured, and it degrades gracefully when the AI is unavailable.
router.post('/ops/ask', rateLimit({ limit: 10 }), async (req, res) => {
  const started = Date.now();
  const question = String(req.body?.question || '').trim().slice(0, 500);
  if (!question) return res.status(400).json({ error: { message: 'Please type a question.' } });

  const key = cacheKey('ask', question);
  const cached = cacheGet(key);
  if (cached) {
    record({ route: 'ask', ms: Date.now() - started, cached: true });
    return res.json({ ...cached, cached: true });
  }

  try {
    const result = await answerQuestion(question, 'hybrid', { timeoutMs: 15000 });
    cacheSet(key, result);
    record({ route: 'ask', ms: Date.now() - started, usage: result.usage });
    return res.json({ ...result, cached: false });
  } catch (e) {
    // Fallback: the AI failed or timed out, so show the best passages instead of an error page.
    record({ route: 'ask', ms: Date.now() - started, fallback: true, error: true });
    console.error('[ops] AI failed:', e?.status || '', e?.message);
    const sources = retrieve(question, { mode: 'hybrid', k: 3 });
    return res.json({
      answer: 'The AI assistant is busy right now. These are the most relevant notes:',
      sources, citations: [], invalidCitations: [], fallback: true, cached: false, usage: { input: 0, output: 0 },
    });
  }
});

// GET /api/ops/metrics
router.get('/ops/metrics', (req, res) => res.json(metrics()));

export default router;

